mapper.update:
UPDATE seinfo_notice
   SET notice_title		= LEFT(#{noticeTitle}, 100)
	 , notice_contents	= LEFT(#{noticeContents}, 100)
	 , notice_d			= DATE_FORMAT(now(), '%Y-%m-%d')
	 , mod_dt			= now()
	 , mod_user_id		= #{userEmail}
 WHERE notice_no = #{noticeNo}
   AND reg_user_id = #{userEmail}

mapper.delete:
DELETE
  FROM seinfo_notice
 WHERE notice_no = #{noticeNo}

	AND reg_user_id = #{userEmail}

mapper.update:
UPDATE seinfo_notice
   SET answer_title		= LEFT(CONCAT('[RE] ', #{answerTitle}), 100)
	 , answer_contents  = LEFT(#{answerContents}, 1000)
	 , answer_d			= DATE_FORMAT(now(), '%Y-%m-%d')
	 , answer_user_id   = #{userId}
	 , mod_dt			= now()
     , mod_user_id		= #{userId}
WHERE notice_no = #{noticeNo}

	AND answer_user_id = #{answerUserId}

mapper.delete:
UPDATE seinfo_notice
   SET answer_contents = NULL
	 , answer_d = NULL
	 , answer_user_id = NULL
	 , mod_dt = now()
	 , mod_user_id = #{userId}
WHERE notice_no = #{noticeNo}
  AND answer_user_id = #{userId}
